import{_ as t,o as a,c as n,a as e}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/relational/distributed/tidb.md","filePath":"data/database/relational/distributed/tidb.md"}'),i={name:"data/database/relational/distributed/tidb.md"};function l(r,s,o,p,h,g){return a(),n("div",null,[...s[0]||(s[0]=[e(`<p>TiDB是一款“计算与存储分离”的分布式数据库，它的设计很精妙：<strong>SQL层、分布式KV存储层、集中式元数据管理层各司其职，共同实现了无限水平扩展、强一致性和高度兼容MySQL的能力</strong>。理解了这三者的分工与协作，你就掌握了TiDB的核心。</p><p>为了帮你快速把握其精髓，下图清晰地展示了TiDB的整体架构与核心组件间的数据流向：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    Client[&quot;应用程序&lt;br&gt;（使用MySQL协议）&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    LoadBalancer[&quot;负载均衡器&lt;br&gt;（如F5, LVS）&quot;]</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph TiDB_Layer [TiDB 计算层（无状态）]</span></span>
<span class="line"><span class="__shiki_140thh">        direction TB</span></span>
<span class="line"><span class="__shiki_140thh">        TIDB1[&quot;TiDB Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        TIDB2[&quot;TiDB Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        TIDB3[&quot;TiDB Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph PD_Layer [PD 调度与元数据层]</span></span>
<span class="line"><span class="__shiki_140thh">        PD1[&quot;PD Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        PD2[&quot;PD Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        PD3[&quot;PD Server&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    subgraph Storage_Layer [TiKV/TiFlash 存储层]</span></span>
<span class="line"><span class="__shiki_140thh">        direction LR</span></span>
<span class="line"><span class="__shiki_140thh">        subgraph TiKV_Group [TiKV（行式存储， OLTP）]</span></span>
<span class="line"><span class="__shiki_140thh">            TIKV1[&quot;TiKV Node&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">            TIKV2[&quot;TiKV Node&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">            TIKV3[&quot;TiKV Node&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        end</span></span>
<span class="line"><span class="__shiki_140thh">        subgraph TiFlash_Group [TiFlash（列式存储， OLAP）]</span></span>
<span class="line"><span class="__shiki_140thh">            TIFLASH1[&quot;TiFlash Node&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">            TIFLASH2[&quot;TiFlash Node&quot;]</span></span>
<span class="line"><span class="__shiki_140thh">        end</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    Client --&gt; LoadBalancer</span></span>
<span class="line"><span class="__shiki_140thh">    LoadBalancer --&gt; TiDB_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    TiDB_Layer -- &quot;1. 查询表数据位置&quot; --&gt; PD_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    PD_Layer -- &quot;2. 返回路由信息&quot; --&gt; TiDB_Layer</span></span>
<span class="line"><span class="__shiki_140thh">    TiDB_Layer -- &quot;3. 读写键值对&quot; --&gt; Storage_Layer</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    TiKV_Group -- &quot;Raft协议同步&quot; --&gt; TiKV_Group</span></span>
<span class="line"><span class="__shiki_140thh">    TiKV_Group -- &quot;实时同步变更&quot; --&gt; TiFlash_Group</span></span></code></pre></div><h3 id="🔍-核心组件深度解析" tabindex="-1">🔍 核心组件深度解析 <a class="header-anchor" href="#🔍-核心组件深度解析" aria-label="Permalink to &quot;🔍 核心组件深度解析&quot;">​</a></h3><p>TiDB架构的核心是三个协同工作的组件，它们各司其职，共同构成了一个高可用的分布式系统：</p><table tabindex="0"><thead><tr><th style="text-align:left;">组件</th><th style="text-align:left;">核心职责</th><th style="text-align:left;">关键特点与实现</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>TiDB Server</strong></td><td style="text-align:left;"><strong>无状态SQL计算层</strong>：接收SQL请求，进行解析、优化并生成分布式执行计划。</td><td style="text-align:left;"><strong>无状态</strong>：可动态增删节点，通过负载均衡器对外提供服务。<strong>计算下推</strong>：将过滤、聚合等计算尽量下推到存储层，减少数据传输。</td></tr><tr><td style="text-align:left;"><strong>TiKV Server</strong></td><td style="text-align:left;"><strong>分布式事务型KV存储引擎</strong>：持久化存储数据，并提供分布式事务与一致性保证。</td><td style="text-align:left;"><strong>Raft共识协议</strong>：数据以<strong>Region</strong>（默认~96MB的连续Key Range）为单位，通过Raft协议在多副本间同步，确保强一致性与高可用。<strong>分布式事务</strong>：基于Google Percolator模型实现跨行跨节点的ACID事务。<strong>Multi-RocksDB</strong>：底层使用RocksDB（LSM-Tree）存储，并将Raft日志与用户数据分离，优化I/O。</td></tr><tr><td style="text-align:left;"><strong>PD Server</strong></td><td style="text-align:left;"><strong>集群的“大脑”</strong>：管理元数据、调度全局并分配唯一递增的事务时间戳。</td><td style="text-align:left;"><strong>元数据管理</strong>：存储整个集群所有Region在TiKV节点上的实时分布映射表。<strong>智能调度</strong>：根据Region负载、副本位置、节点状态等信息，自动进行负载均衡、副本迁移、Leader重选等，是集群弹性和高可用的核心。<strong>时间戳授时</strong>：提供全局唯一且严格递增的时间戳，是实现分布式事务和MVCC的基石。</td></tr></tbody></table><h3 id="🧱-关键技术设计与实现" tabindex="-1">🧱 关键技术设计与实现 <a class="header-anchor" href="#🧱-关键技术设计与实现" aria-label="Permalink to &quot;🧱 关键技术设计与实现&quot;">​</a></h3><p>理解了宏观架构后，我们再深入到几个关键技术点：</p><ol><li><p><strong>数据如何从“表”变成“键值对”？</strong> 这是TiDB能融合关系模型与分布式存储的关键。它通过一套编码规则，将SQL表的一行数据映射为一个或多个KV对。例如，主键为<code>1</code>的<code>user</code>表某行数据，可能会被编码为 <code>t{表ID}_r1</code> 这样的Key，其Value则包含了该行所有列的数据。这种映射使得数据可以均匀地分布在TiKV集群的多个Region中。</p></li><li><p><strong>分布式事务如何工作？</strong> TiDB默认采用<strong>悲观锁</strong>模型。其事务核心基于 <strong>Percolator模型</strong> 的两阶段提交（2PC）实现：</p><ul><li><strong>Prewrite（预写）</strong>：事务协调者（TiDB）将所有要写的Key中选一个作为<strong>Primary Key</strong>，然后并发地向所有涉及到的TiKV发起预写请求，对数据加锁并写入新版本。</li><li><strong>Commit（提交）</strong>：预写全部成功后，协调者从PD获取全局递增的<code>commit_ts</code>，然后先提交Primary Key。一旦Primary提交成功，整个事务即被视为成功，后续异步提交其他Secondary Keys。</li></ul></li><li><p><strong>一条SQL查询是如何被执行的？</strong></p><ul><li><strong>解析与优化</strong>：TiDB Server接收到SQL后，进行词法语法分析，生成抽象语法树，然后经过一系列基于规则和成本的优化，生成最优的<strong>物理执行计划</strong>。</li><li><strong>分布式执行</strong>：优化器将计划拆分为多个子任务。例如，一个涉及多表Join的查询，可能会被转换为在不同TiKV节点上并行扫描数据、进行局部聚合，再由TiDB Server进行最终汇总的模式。</li></ul></li><li><p><strong>如何避免热点与实现弹性扩展？</strong></p><ul><li><strong>Region自动分裂与调度</strong>：当一个Region数据量增长到阈值（如144MB），PD会触发其分裂。同时，PD的调度器会持续监控所有TiKV节点的负载，通过在节点间迁移Region来自动实现<strong>负载均衡</strong>，整个过程对业务透明。</li><li><strong>热点散列</strong>：对于不含主键或使用自增整型主键的表，大量写入可能集中在一个Region。TiDB提供了 <code>SHARD_ROW_ID_BITS</code> 等特性，将行ID打散到多个Region，有效缓解写入热点。</li></ul></li></ol><h3 id="💡-对比与场景思考" tabindex="-1">💡 对比与场景思考 <a class="header-anchor" href="#💡-对比与场景思考" aria-label="Permalink to &quot;💡 对比与场景思考&quot;">​</a></h3><p>通过与CockroachDB对比，可以更深刻理解TiDB的设计哲学：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;"><strong>TiDB</strong></th><th style="text-align:left;"><strong>CockroachDB (与你上篇笔记对比)</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>架构哲学</strong></td><td style="text-align:left;"><strong>分层解耦，计算与存储分离</strong>。</td><td style="text-align:left;">一体化架构，每个节点功能对等。</td></tr><tr><td style="text-align:left;"><strong>一致性核心</strong></td><td style="text-align:left;">PD中心化授时 + TiKV Raft组。</td><td style="text-align:left;">基于HLC（混合逻辑时钟）的去中心化时间戳。</td></tr><tr><td style="text-align:left;"><strong>事务模型</strong></td><td style="text-align:left;">默认悲观事务，基于Percolator的2PC。</td><td style="text-align:left;">默认乐观事务，在提交阶段进行冲突检测。</td></tr><tr><td style="text-align:left;"><strong>扩展性</strong></td><td style="text-align:left;"><strong>计算层（TiDB）和存储层（TiKV）可独立横向扩展</strong>。</td><td style="text-align:left;">所有节点对等，通过增加节点实现整体扩展。</td></tr></tbody></table><h4 id="如何选择" tabindex="-1">如何选择？ <a class="header-anchor" href="#如何选择" aria-label="Permalink to &quot;如何选择？&quot;">​</a></h4><ul><li><strong>优先考虑TiDB的场景</strong>：业务强依赖MySQL生态和语法，希望平滑迁移；明确需要计算与存储分离的架构，或希望独立扩展计算/存储资源；需要一体化的HTAP能力（结合TiFlash列存引擎）进行实时分析。</li><li><strong>可能需要考虑CockroachDB的场景</strong>：业务部署在多地域、多数据中心，且对<strong>全球强一致</strong>和异地容灾有极高要求；更倾向于完全去中心化的架构，避免任何单点瓶颈（尽管PD本身是高可用的）。</li></ul><h3 id="🔮-演进与展望" tabindex="-1">🔮 演进与展望 <a class="header-anchor" href="#🔮-演进与展望" aria-label="Permalink to &quot;🔮 演进与展望&quot;">​</a></h3><p>TiDB架构也在持续演进，例如引入<strong>TiFlash</strong>作为分析型列存引擎，通过Raft Learner机制从TiKV实时同步数据，实现了<strong>HTAP</strong>（混合事务/分析处理）的能力，让一份数据同时服务在线交易和实时分析。此外，面向云原生，<strong>TiDB Operator</strong>项目实现了在Kubernetes上对TiDB集群的全生命周期自动化管理。</p><p>希望这份笔记能帮你建立起对TiDB设计与实现的清晰框架。如果你对其中某个技术细节，比如Raft在TiKV中的具体实现、或者优化器的工作原理有进一步的兴趣，我们可以继续深入探讨。</p>`,17)])])}const d=t(i,[["render",l]]);export{c as __pageData,d as default};
